from pathlib import Path
import json
import re
# Embed one shared presentation layer in every first-party page. No extra asset request.
ui_css=Path('ui-theme.css').read_text()
for page in ['dist/index.html','dist/learnings.html','telegram-connect.html','telegram-guide.html','dist/naam-japa.html']:
 page_path=Path(page)
 source=page_path.read_text()
 source=re.sub(r'<style id="radar-ui-system">.*?</style>', '', source, flags=re.S)
 theme='<style id="radar-ui-system">'+ui_css+'</style>'
 # Telegram's compact documents have an implicit head.
 source=source.replace('</head>',theme+'</head>',1) if '</head>' in source else source.replace('<main>',theme+'<main>',1)
 page_path.write_text(source)
desk=Path('telegram-news.js').read_text()+'\n'+Path('delta-desk.js').read_text()+'\n'+Path('performance.js').read_text()+'\n'+Path('learnings.js').read_text()+'\n'+Path('deep-review.js').read_text()+'\n'+Path('fyers.js').read_text()
shark_desk=Path('shark-desk.js').read_text()
whatsapp=Path('whatsapp.js').read_text()
demo=Path('demo-desk.js').read_text()
background=Path('background.js').read_text()
monitor=Path('trade-monitor.js').read_text()
surge=Path('surge-scanner.js').read_text()
custom=Path('custom-alerts.js').read_text()
custom_rules=Path('dist/custom-alert-rules.js').read_text()
html=Path('dist/index.html').read_text()
js=Path('dist/app.js').read_text()
stocks=Path('dist/stocks.js').read_text()+'\n'+Path('dist/market-accounts.js').read_text()+'\n'+Path('dist/learnings.js').read_text()
signals=Path('dist/signals.js').read_text()
customer_flow=Path('dist/customer-flow.js').read_text()
socketio=Path('dist/vendor/socket.io.js').read_text()
lwc=Path('dist/vendor/lightweight-charts.js').read_text()
license=Path('dist/vendor/LICENSE.txt').read_text()+'\n'+Path('dist/vendor/NOTICE.txt').read_text()+'\n'+Path('dist/vendor/SOCKET-LICENSE.txt').read_text()
worker='''const JAPA_HTML=__JAPA_HTML__;const JAPA_JS=__JAPA_JS__;const TELEGRAM_POSTS=__TELEGRAM_POSTS__;const TELEGRAM_GUIDE=__TELEGRAM_GUIDE__;const DEEP_JS=__DEEP_JS__;const LEARNING_HTML=__LEARNING_HTML__;const LEARNING_JS=__LEARNING_JS__;const STOCKS=__STOCKS__;const SOCKETIO=__SOCKETIO__;const LWC = __LWC__;const LICENSE = __LICENSE__;const HTML = __HTML__;\nconst APP = __APP__;\nconst SIGNALS = __SIGNALS__;const CUSTOMER_FLOW=__CUSTOMER_FLOW__;\nconst allowed = {delta:'https://api.india.delta.exchange',shark:'https://api.sharkexchange.in'};\nexport default {async fetch(request,env){\n const u=new URL(request.url);if(u.pathname==='/naam-japa'||u.pathname==='/naam-japa/')return new Response(JAPA_HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/naam-japa.js')return new Response(JAPA_JS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/telegram-posts.js')return new Response(TELEGRAM_POSTS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/telegram-connect'||u.pathname==='/telegram-connect/')return new Response(TELEGRAM_GUIDE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-frame-options':'DENY'}});if(u.pathname==='/api/telegram-news')return telegramNewsRoute(request);if(u.pathname==='/learnings'||u.pathname==='/learnings/')return new Response(LEARNING_HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/deep-review.js')return new Response(DEEP_JS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/learnings.js')return new Response(LEARNING_JS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname.startsWith('/api/fyers/'))return fyersRoute(request,env);if(u.pathname==='/stocks.js')return new Response(STOCKS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/api/custom-alerts')return customRoute(request,env);if(u.pathname==='/custom-alert-rules.js')return new Response(CUSTOM_RULES,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/api/surge/run')return surgeServiceRoute(request,env);if(u.pathname==='/api/surge')return surgeRoute(request,env);if(u.pathname==='/api/trade-monitor'||u.pathname==='/api/trade-monitor/run')return monitorRoute(request,env);if(u.pathname==='/api/background'||u.pathname==='/api/background/run')return backgroundRoute(request,env);if(u.pathname==='/api/demo')return demoRoute(request,env);if(u.pathname==='/api/whatsapp')return whatsappRoute(request,env);if(u.pathname.startsWith('/api/delta-desk/'))return deskRoute(request,env);if(u.pathname.startsWith('/api/shark-desk/'))return sharkDeskRoute(request,env);if(u.pathname==='/vendor/socket.io.js')return new Response(SOCKETIO,{headers:{'content-type':'application/javascript'}});if(u.pathname==='/vendor/lightweight-charts.js')return new Response(LWC,{headers:{'content-type':'application/javascript; charset=utf-8'}});if(u.pathname==='/vendor/LICENSE.txt')return new Response(LICENSE,{headers:{'content-type':'text/plain; charset=utf-8'}});\n if(u.pathname==='/'||u.pathname==='/index.html')return new Response(HTML,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}});\n if(u.pathname==='/customer-flow.js')return new Response(CUSTOMER_FLOW,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});\n if(u.pathname==='/signals.js')return new Response(SIGNALS,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});\n if(u.pathname==='/app.js')return new Response(APP,{headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'no-store'}});\nconst m=u.pathname.match(/^\\/api\\/(delta|shark)\\/(v[12]\\/.*)$/);\n if(!m)return new Response('Not found',{status:404});\n if(request.method!=='GET'&&!(m[1]==='shark'&&request.method==='POST'&&u.pathname==='/api/shark/v1/market/klines'))return new Response('Method not allowed',{status:405});\n const path='/'+m[2];\n const ok=m[1]==='delta'?(/^\\/v2\\/(tickers(?:\\/[A-Z0-9]+)?|history\\/candles|products\\/[A-Z0-9]+|l2orderbook\\/[A-Z0-9]+)$/.test(path)):(/^\\/v1\\/exchange\\/exchangeInfo$/.test(path)||/^\\/v1\\/market\\/ticker24Hr\\/[A-Z0-9]+$/.test(path)||/^\\/v1\\/market\\/depth\\/[A-Z0-9]+$/.test(path)||path==='/v1/market/klines');\n if(!ok)return new Response('Not found',{status:404});\n try {const target=allowed[m[1]]+path+u.search;const response=await fetch(target,{method:request.method,signal:AbortSignal.timeout(12000),headers:{accept:'application/json','content-type':'application/json','user-agent':'MarketRadar/1.0 (+https://chatgpt.site)'},body:request.method==='POST'?await request.text():undefined});return new Response(response.body,{status:response.status,headers:{'content-type':'application/json','cache-control':'no-store'}})}catch(e){return new Response(JSON.stringify({error:'Exchange feed unavailable'}),{status:502,headers:{'content-type':'application/json'}})}\n}};\n'''
worker=worker.replace('__JAPA_HTML__',json.dumps(Path('dist/naam-japa.html').read_text())).replace('__JAPA_JS__',json.dumps(Path('dist/naam-japa.js').read_text())).replace('__TELEGRAM_POSTS__',json.dumps(Path('dist/telegram-posts.js').read_text())).replace('__TELEGRAM_GUIDE__',json.dumps(Path('telegram-guide.html').read_text())).replace('__DEEP_JS__',json.dumps(Path('dist/deep-review.js').read_text())).replace('__LEARNING_HTML__',json.dumps(Path('dist/learnings.html').read_text())).replace('__LEARNING_JS__',json.dumps(Path('dist/learnings.js').read_text())).replace('__STOCKS__',json.dumps(stocks)).replace('__CUSTOMER_FLOW__',json.dumps(customer_flow)).replace('__SOCKETIO__',json.dumps(socketio)).replace('__LWC__',json.dumps(lwc)).replace('__LICENSE__',json.dumps(license)).replace('__HTML__',json.dumps(html,ensure_ascii=False)).replace('__APP__',json.dumps(js,ensure_ascii=False)).replace('__SIGNALS__',json.dumps(signals,ensure_ascii=False))
worker='const CUSTOM_RULES='+json.dumps(custom_rules)+';const customRules=(()=>{const window={};'+custom_rules+';return window.CustomAlertRules;})();\n'+custom+'\n'+'const backgroundStrategy=(()=>{const window={};'+signals+';return window.StrategySignals;})();\n'+background+'\n'+monitor+'\n'+surge+'\n'+demo+'\n'+desk+'\n'+shark_desk+'\n'+whatsapp+'\n'+worker
out=Path('dist/server/index.js');out.parent.mkdir(parents=True,exist_ok=True);out.write_text(worker)
